#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using Catamailer.Domain;

namespace Catamailer.Application
{
    /// <summary>
    /// Moteur d'évaluation de l'Étape 1 : déduction des catégories en fonction des dictionnaires de mots-clés contextuels.
    /// </summary>
    public class ClassificationEngine
    {
        /// <summary>
        /// Évalue les métadonnées d'un e-mail par rapport à un ensemble de règles de dictionnaire et retourne la première correspondance.
        /// </summary>
        /// <param name="metadata">Les métadonnées extraites de l'e-mail.</param>
        /// <param name="rules">La collection des règles de dictionnaire à évaluer.</param>
        /// <returns>Le premier résultat de la classification contenant la catégorie cible et son ascendance, ou null si aucune règle ne correspond.</returns>
        public ClassificationResult? Classify(MailMetadata metadata, IEnumerable<DictionaryRule> rules)
        {
            return ClassifyAll(metadata, rules).FirstOrDefault();
        }

        /// <summary>
        /// Évalue l'intégralité des règles de dictionnaire sur les métadonnées d'un e-mail (parité VBA) et retourne toutes les catégories déclenchées avec leur déclencheur exact.
        /// </summary>
        /// <param name="metadata">Les métadonnées extraites de l'e-mail.</param>
        /// <param name="rules">La collection des règles de dictionnaire à évaluer.</param>
        /// <returns>La liste complète des correspondances détectées.</returns>
        public IReadOnlyList<ClassificationResult> ClassifyAll(MailMetadata metadata, IEnumerable<DictionaryRule> rules)
        {
            var results = new List<ClassificationResult>();

            if (rules == null || !rules.Any() || metadata == null)
            {
                return results;
            }

            var sendersToMatch = new List<string>();
            if (!string.IsNullOrWhiteSpace(metadata.Sender))
            {
                sendersToMatch.Add(metadata.Sender);
            }
            if (!string.IsNullOrWhiteSpace(metadata.OnBehalfOf))
            {
                sendersToMatch.Add(metadata.OnBehalfOf);
            }

            var recipientsToMatch = new List<string>();
            if (metadata.InternalRecipients != null)
            {
                recipientsToMatch.AddRange(metadata.InternalRecipients.Where(r => !string.IsNullOrWhiteSpace(r)));
            }
            if (metadata.ExternalRecipients != null)
            {
                recipientsToMatch.AddRange(metadata.ExternalRecipients.Where(r => !string.IsNullOrWhiteSpace(r)));
            }

            var subject = metadata.Subject ?? string.Empty;

            foreach (var rule in rules)
            {
                // 1. Recherche dans les mots-clés du sujet
                var matchedSubjectKeyword = rule.SubjectKeywords.FirstOrDefault(k =>
                    !string.IsNullOrWhiteSpace(k) && subject.Contains(k, StringComparison.OrdinalIgnoreCase));

                if (matchedSubjectKeyword != null)
                {
                    results.Add(new ClassificationResult(
                        rule.TargetCategory,
                        rule.TargetCategory.GetAscendanceChain(),
                        MailField.Subject,
                        matchedSubjectKeyword,
                        subject));
                    continue;
                }

                // 2. Recherche dans les mots-clés de l'expéditeur
                string? matchedSenderKeyword = null;
                string? matchedSenderValue = null;
                foreach (var keyword in rule.SenderKeywords.Where(k => !string.IsNullOrWhiteSpace(k)))
                {
                    var senderHit = sendersToMatch.FirstOrDefault(s =>
                        s.Contains(keyword, StringComparison.OrdinalIgnoreCase));
                    if (senderHit != null)
                    {
                        matchedSenderKeyword = keyword;
                        matchedSenderValue = senderHit;
                        break;
                    }
                }

                if (matchedSenderKeyword != null)
                {
                    results.Add(new ClassificationResult(
                        rule.TargetCategory,
                        rule.TargetCategory.GetAscendanceChain(),
                        MailField.Sender,
                        matchedSenderKeyword,
                        matchedSenderValue ?? string.Empty));
                    continue;
                }

                // 3. Recherche dans les mots-clés des destinataires
                string? matchedRecipientKeyword = null;
                string? matchedRecipientValue = null;
                foreach (var keyword in rule.RecipientKeywords.Where(k => !string.IsNullOrWhiteSpace(k)))
                {
                    var recipientHit = recipientsToMatch.FirstOrDefault(r =>
                        r.Contains(keyword, StringComparison.OrdinalIgnoreCase));
                    if (recipientHit != null)
                    {
                        matchedRecipientKeyword = keyword;
                        matchedRecipientValue = recipientHit;
                        break;
                    }
                }

                if (matchedRecipientKeyword != null)
                {
                    results.Add(new ClassificationResult(
                        rule.TargetCategory,
                        rule.TargetCategory.GetAscendanceChain(),
                        MailField.Recipients,
                        matchedRecipientKeyword,
                        matchedRecipientValue ?? string.Empty));
                }
            }

            return results;
        }
    }
